        /// <summary>
        /// 容器中按钮通用触发事件
        /// </summary>
        /// <param name="ButtonName">按钮名</param>
        public void ButtonClick(string ButtonName)
        {
		    //to do..
			
		    #region 判断打印机、模板、数据源是否为空？
			if(ButtonName=="PrintJudgement")
			{
					
					//判断是否打印彩盒
					if(Scripter.GetParameterValue("IsGiftBox")=="False")
					{
					  return;
					}
			        //判断打印机是否为空
					for(int i=0;i<LabelCount;i++)
					{
						if(Scripter.GetParameterValue("DC CollectPrint Setting.Printer"+Convert.ToString(i+1))=="")
						{
							MessageBox.Show("请选择打印机!");
							return ;
						}	
						
						if(Scripter.GetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1))=="")
						{
							MessageBox.Show("模板路径下载异常!");
							Scripter.ShowMessage(Scripter.GetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1)),false);
							return ;
						}
						if(Scripter.GetParameterValue("LabelDataSource"+Convert.ToString(i+1))=="")
						{
							MessageBox.Show("请先维护标签数据源!");
							Scripter.ShowMessage(Scripter.GetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1)),false);
							return ;
						}
						if(Scripter.GetParameterValue("DC CollectPrint Setting.PrintCopies"+Convert.ToString(i+1))=="")
						{
							MessageBox.Show("请先维护打印份数!");
							return ;
						}
					}
			}
			#endregion
			
		    #region 锁定 取消锁定
			if(ButtonName=="LockData")
			{
				if(Scripter.GetParameterValue("IsLock")=="")
				{
					Scripter.SetControlStyle("OrderName","[Enable|0]");
					Scripter.SetControlStyle("Operator","[Enable|0]");
					Scripter.SetParameterValue("IsLock","Y");
					Scripter.MESTxnPanel.Controls["btn_LockData"].Text="解锁";
//					Scripter.SetParameterValue("IsGiftBox","True");
				    Scripter.SetControlStyle("IsGiftBox","[Enable|0]");

					Scripter.SetControlStyle("DC CollectPrint Setting.Printer1","[Enable|0]");
					Scripter.SetControlStyle("DC CollectPrint Setting.Printer2","[Enable|0]");
					Scripter.SetControlStyle("DC CollectPrint Setting.Printer3","[Enable|0]");
				    Scripter.SetControlStyle("DC CollectPrint Setting.PrintCopies1","[Enable|0]");
					Scripter.SetControlStyle("DC CollectPrint Setting.PrintCopies2","[Enable|0]");
					Scripter.SetControlStyle("DC CollectPrint Setting.PrintCopies3","[Enable|0]");
				}
				else
				{
				    Scripter.SetControlStyle("OrderName","[Enable|1]");
					Scripter.SetControlStyle("Operator","[Enable|1]");
					Scripter.SetParameterValue("IsLock","");
					Scripter.MESTxnPanel.Controls["btn_LockData"].Text="锁定";
//					Scripter.SetParameterValue("IsGiftBox","False");
					 Scripter.SetControlStyle("IsGiftBox","[Enable|1]");
				    Scripter.SetControlStyle("DC CollectPrint Setting.Printer1","[Enable|1]");
					Scripter.SetControlStyle("DC CollectPrint Setting.Printer2","[Enable|1]");
					Scripter.SetControlStyle("DC CollectPrint Setting.Printer3","[Enable|1]");
					Scripter.SetControlStyle("DC CollectPrint Setting.PrintCopies1","[Enable|1]");
					Scripter.SetControlStyle("DC CollectPrint Setting.PrintCopies2","[Enable|2]");
					Scripter.SetControlStyle("DC CollectPrint Setting.PrintCopies3","[Enable|3]");
					
				}
			}
			#endregion
			
			#region 彩盒扫描
			if(ButtonName=="PackOnLine")
			{
				for (int i=0;i<grid.DisplayLayout.Bands[0].ColumnFilters.Count;i++)
				{
					if(Convert.ToString(grid.DisplayLayout.Bands[0].Columns[i].Header.Caption)=="SN")
					{
						grid.DisplayLayout.Bands[0].Columns[i].Width=250;
					}
				}
			}
			#endregion
			
			#region 下载标签模板
			if (ButtonName=="DownLoadLabel")
			{	

				//路径
		        string spath=@"D:\MES_Label\"+Scripter.GetParameterValue("OrderName")+@"\";
			   
				//处理本地模板				
				if(Scripter.GetParameterValue("OrderName")=="")
				{
					MessageBox.Show("请选择订单!",Scripter.PlugInCommand);
					return ;
				}
				
				string a="";
				bool Down=true;
				DataSet ds=new DataSet();
				
			    ds=LabelDownloadFile(ref a);
				
				if(a=="-1")
				{
				    MessageBox.Show("请先维护订单标签!",Scripter.PlugInCommand);
					return ;
				}
				//计算选择当前订单模板数量
				LabelCount=ds.Tables[0].Rows.Count; 

				//如果路径不存在就创建file文件夹
			    if (Directory.Exists(spath))
				{
					for(int i=0;i<ds.Tables[0].Rows.Count;i++)
					{						

						if (MessageBox.Show("路径："+spath+Convert.ToString(ds.Tables[0].Rows[i][1])+" 模板是否覆盖?", "警告！！！", MessageBoxButtons.OKCancel, MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2) == DialogResult.OK)
						{
							Down=Scripter.DownloadFile(Convert.ToString(ds.Tables[0].Rows[i][0]),spath+Convert.ToString(ds.Tables[0].Rows[i][1]),"");
							Scripter.SetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1),spath+Convert.ToString(ds.Tables[0].Rows[i][1])); 
							Scripter.SetParameterValue("LabelId"+Convert.ToString(i+1),Convert.ToString(ds.Tables[0].Rows[i][2])); 
							Scripter.SetParameterValue("LabelDataSource"+Convert.ToString(i+1),Convert.ToString(ds.Tables[0].Rows[i][3]));
							
						}
						else
						{
							Scripter.SetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1),spath+Convert.ToString(ds.Tables[0].Rows[i][1])); 
							Scripter.SetParameterValue("LabelId"+Convert.ToString(i+1),Convert.ToString(ds.Tables[0].Rows[i][2])); 
							Scripter.SetParameterValue("LabelDataSource"+Convert.ToString(i+1),Convert.ToString(ds.Tables[0].Rows[i][3])); 
							MessageBox.Show("路径："+spath+Convert.ToString(ds.Tables[0].Rows[i][1]),"已取消覆盖");
						}		
					}
				}
				else
				{
					for(int i=0;i<ds.Tables[0].Rows.Count;i++)
					{						
		
						DirectoryInfo directoryInfo = new DirectoryInfo(spath);
					    directoryInfo.Create();
						Down=Scripter.DownloadFile( Convert.ToString(ds.Tables[0].Rows[i][0]),spath+Convert.ToString(ds.Tables[0].Rows[i][1]),"");
						Scripter.SetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1),spath+Convert.ToString(ds.Tables[0].Rows[i][1])); 
						Scripter.SetParameterValue("LabelId"+Convert.ToString(i+1),Convert.ToString(ds.Tables[0].Rows[i][2])); 
						Scripter.SetParameterValue("LabelDataSource"+Convert.ToString(i+1),Convert.ToString(ds.Tables[0].Rows[i][3])); 
						Scripter.ShowMessage("路径：【"+spath+Convert.ToString(ds.Tables[0].Rows[i][1]) +" 】 模板下载成功",false);	

					}	
				}
			}
			#endregion
			
			#region 打印彩盒
			if(ButtonName=="LotSNPrint")
			{
				//判断是否打印彩盒
				if(Scripter.GetParameterValue("IsGiftBox")=="False")
				{
				  return;
				}
				try
				{
					DataSet rds=new DataSet();
		
					string returnMessage="";
					if(Scripter.GetParameterValue("IsPrint")!="1")
					{
						return ;
					}
					
					//获取外箱数据集
	                for(int i=0;i<LabelCount;i++)
					{
						if(PrintBoxData(Scripter.GetParameterValue("LabelId"+Convert.ToString(i+1)),ref returnMessage,ref rds)==-1)
						{
							MessageBox.Show(returnMessage+Scripter.GetParameterValue("IsPrint"));
							return;
						}
						
						for(int j=0;j<rds.Tables.Count;j++)
						{
							if(j>0)
							{
								rds.Tables.RemoveAt(j);
							}
						}
						if (rds==null)
						{
						   
							MessageBox.Show("打印标签信息数据为空");
							return;
						}
						
						//设置外箱标签默认打印机
						SetDefaultPrinter(Scripter.GetParameterValue("DC CollectPrint Setting.Printer"+Convert.ToString(i+1)));

						//打印本地模板
						int a=int.Parse(Scripter.GetParameterValue("DC CollectPrint Setting.PrintCopies"+Convert.ToString(i+1)));

						for(int k=0;k<a;k++)
						{
						   Scripter.PrintMRZReport(Scripter.GetParameterValue("DC CollectPrint Setting.LabelName"+Convert.ToString(i+1)),rds,false);	
						}
	
					}		
				}
				catch(Exception ex)
				{
					MessageBox.Show(ex.Message);			
				}
			}
			#endregion
			
			//选中行
			if (ButtonName=="SelRow")
			{	
				try
				{							
					string NextItemName=Scripter.GetParameterValue("NextItemName");
					
					for(int i=0;i<grid.Rows.Count;i++)
					{
						if (Convert.ToString(grid.Rows[i].Cells["CollectItemName"].Value)==NextItemName)
						{
							grid.Rows[i].Selected=true;
						}
						else
						{
							grid.Rows[i].Selected=false;
						}
					}
				}
				catch{}
			}		
				
        }

