       /// <summary>
		/// 打印彩盒数据
		/// </summary>
		public int PrintBoxData(string LabelId, ref string returnMessage,ref DataSet rds)
        {		
		    int result=-1;
			string OrderName="";
			returnMessage="";
			
			OrderName=Scripter.GetParameterValue("OrderName");
			string Operator=Scripter.GetParameterValue("Operator");
            string I_ResourceId=Scripter.ResourceId;
			string TLotSN=Scripter.GetParameterValue("TLotSN");
			
			try
			{
				string str=@"DECLARE @return_value int,
									@I_ReturnMessage nvarchar(max)

						EXEC @return_value = [dbo].[Txn_DCPrintLabelAuto]
							@I_ReturnMessage =@I_ReturnMessage OUTPUT,
							@Operator = N'"+Operator+@"',							
							@I_ResourceId = N'"+I_ResourceId+@"',
						    @OrderName = N'"+OrderName+@"',
							@LotSN =N'"+TLotSN+@"',
							@kgWeight =N'"+kgWeight+@"',
                            @LabelId =N'"+LabelId+@"'

                     SELECT   @return_value as N'return_value',
                             @I_ReturnMessage as N'I_ReturnMessage' ";				

				//执行 SQL 语句
				rds=Scripter.GetSqlDataSet(str);
				
				if(rds.Tables.Count==0)
				{
					result=-1;
				}
				
				if(rds.Tables.Count==1)
				{
					result=Convert.ToInt32(rds.Tables[0].Rows[0]["return_value"]);
					returnMessage=Convert.ToString(rds.Tables[0].Rows[0]["I_ReturnMessage"]);
				}
				
				if(rds.Tables.Count==2)
				{
					result=Convert.ToInt32(rds.Tables[1].Rows[0]["return_value"]);
					returnMessage=Convert.ToString(rds.Tables[1].Rows[0]["I_ReturnMessage"]);
				}
			}
			catch(Exception ex)
			{
				returnMessage=ex.Message;			
			}
			
			return result ;
		}
		
        /// 获取模板集
		/// </summary>
		public  DataSet LabelDownloadFile(ref string return_value)
        {
			
		    DataSet ds=null;
			string OrderFieldSettingId= Scripter.GetParameterValue("OrderFieldSettingId");
			string MESTxnName=Scripter.MESTxnName;
			
			try
			{
			string str=@"DECLARE	@return_value int

							EXEC	@return_value = [dbo].[LabelDownloadFileDoMethod]
                                   @OrderFieldSettingId = N'"+OrderFieldSettingId+@"',
                                   @MESTxnName =N'"+MESTxnName+@"'


								SELECT @return_value as N'return_value' ";				

				//执行 SQL 语句
			    ds=Scripter.GetSqlDataSet(str);
				return_value=Convert.ToString(ds.Tables[1].Rows[0]["return_value"]);

				
			}
			catch(Exception ex)
			{
				MessageBox.Show(ex.Message);
				
			}
			
			return ds;
		}
    }
