        public OrBitScript.OrBitAPI Scripter = new OrBitScript.OrBitAPI(); 
		SerialPort serialPort=new SerialPort();
		System.Timers.Timer CTTimer=null;
		string CurPort="";
		DataTable PDt=new DataTable();		//端口表
		DataSet PDs=new DataSet();			//端口的数据集
		int i=1;
		bool IsConnect=false;		//端口是否打开
		int k=0;

		Infragistics.Win.UltraWinEditors.UltraTextEditor text=null;  //实例化text	
		
        /// <summary>
        /// 脚本对象实例化时加载时的方法
        /// </summary>
        public void ScriptLoad()
        {
			string [] portStr=SerialPort.GetPortNames();
			DataRow PRow=null;
			PDt.Columns.Add("Port");			
			foreach(string elm in portStr)
			{
				PRow=PDt.NewRow();
				PRow[0]=elm.ToString();
				PDt.Rows.Add(PRow);
				PRow=null;
			}
			
			PDs.Tables.Add(PDt);
			Scripter.SetParameterDataSet("SetPort",PDs);
			//从服务器取得端口参数
			DataSet gDs=getPortSetting();
			if(Convert.ToString(gDs.Tables[0].Rows[0]["return_value"])=="0")
			{
				Scripter.SetParameterValue("SetPort",gDs.Tables[0].Rows[0]["Port"].ToString());
				Scripter.SetParameterValue("DelayTime",gDs.Tables[0].Rows[0]["DelayTime"].ToString());
			}
			else	//使用默认端口参数	
			{
				Scripter.SetParameterValue("SetPort",PDs.Tables[0].Rows[0][0].ToString());
				Scripter.SetParameterValue("DelayTime","20");
				Scripter.ShowMessage(gDs.Tables[0].Rows[0]["I_ReturnMessage"].ToString() ,true);
			}

			CurPort=Scripter.GetParameterValue("SetPort");
			Scripter.SetParameterValue("Ports",CurPort);	
			Scripter.MESTxnPanel.Controls["PortStaus"].Text="端口关闭";
			Scripter.SetParameterValue("WarnImage","disconnect.png");
		
			//打开端口
			IsConnect=OpenPort(CurPort);			
			if(IsConnect)
			{
				Scripter.MESTxnPanel.Controls["PortStaus"].Text="端口已打开";
				Scripter.SetParameterValue("WarnImage","connect.png");
			}
			Scripter.SetControlStyle("SetPort","[CombEdit|0]");
			text=(Infragistics.Win.UltraWinEditors.UltraTextEditor)Scripter.MESTxnPanel.Controls["IsMove"] ;
			text.ValueChanged += new System.EventHandler(this.text_ValueChanged);
			CTTimer =new System.Timers.Timer(1000);
			CTTimer.AutoReset=true;
			CTTimer.Elapsed+=new ElapsedEventHandler(TimeoutEvent);
			CTTimer.Enabled=true;
        }
		
		public void TimeoutEvent(object sender, EventArgs e)
		{
			if(Scripter.GetParameterValue("IsMove")=="W")
			{
				if(k>=Convert.ToInt32(Scripter.GetParameterValue("DelayTime")))
				{
					k=0;
					Scripter.SetParameterValue("DC AccessoryCollect.Times",k.ToString());
					Scripter.RS232Object.RtsEnable=false;
					Scripter.SetParameterValue("IsMove","");
					Scripter.ShowMessage("停止!" ,true);						
					return ;
				}
				
				k=k+1;
				Scripter.SetParameterValue("DC AccessoryCollect.Times",k.ToString());
			}
		}
				
		public void text_ValueChanged(object sender, EventArgs e)
		{
			if(Scripter.GetParameterValue("DC AccessoryCollect.IsMove")=="")
			{
				return ;
			}
			
			if(Scripter.GetParameterValue("IsMove")=="Y" && Scripter.GetParameterValue("IsMove")!="W") 
			{	
				Scripter.RS232Object.RtsEnable=true;
				Scripter.SetParameterValue("IsMove","W");
				Scripter.SetParameterValue("DC AccessoryCollect.IsMove","");
				Scripter.ShowMessage("开启" ,true);
				k=0;
			}
		}
		public DataSet getPortSetting()
		{			
			string I_OrBitUserId=Scripter.OrBitUserId;
			string I_OrBitUserName=Scripter.OrBitUserName;
			string I_ResourceId=Scripter.ResourceId;
			string I_ResourceName=Scripter.ResourceName;
			string returnMessage="";
			string ExceptionFieldName="";
			string str=@"DECLARE @return_value int,
							@DelayTime int=0,
							@Port nvarchar(50)='',
							@I_ExceptionFieldName nvarchar(100),
							@I_ReturnMessage nvarchar(max)					
				EXEC @return_value = [dbo].[Txn_PortSettingGet]
					@I_ReturnMessage = @I_ReturnMessage output ,
					@I_ExceptionFieldName=@I_ExceptionFieldName output ,
					@DelayTime=@DelayTime output,
					@Port=@Port output,
